/**
 * Directory listings for public assets are resolved from a build-time manifest
 * (generated by scripts/public-assets-manifest.ts) instead of fs.readdirSync,
 * so serverless functions never need the `public/` files on disk.
 */
import manifest from "@/generated/public-assets-manifest.json";

const directoryIndex = manifest as Record<string, string[]>;

function normalizeDir(dir: string): string {
  if (!dir) return "/";
  const withLeadingSlash = dir.startsWith("/") ? dir : `/${dir}`;
  return withLeadingSlash.length > 1
    ? withLeadingSlash.replace(/\/+$/, "")
    : withLeadingSlash;
}

export function getSliderImages(path2: string): string[] {
  return directoryIndex[normalizeDir(path2)] ?? [];
}
